// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Recorder rec;

    function setUp() public { c = new MyContract(); rec = new Recorder(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= type(uint256).max / 2);
        vm.assume(actor != address(0));
        // owner is the deployer (this test contract), so prank as it
        vm.deal(address(c), amount); // ensure the contract can pay the full amount
        vm.prank(address(this));
        c.sendTo(address(rec), amount);
        // General rule: the receiver's balance increased by at least the requested amount.
        assertTrue(address(rec).balance >= amount);
    }
}

contract Recorder {
    fallback() external payable {}
    receive() external payable {}
}
